   898→            <span class="panel-count" id="heading-count-sub"></span>
   899→          </div>
   900→        </div>
   901→        <div id="heading-list" class="heading-list"></div>
   902→      </div>
   903→
   904→      <!-- JSON -->
   905→      <div id="tab-json" class="tab-panel">
   906→        <div class="panel-hd">
   907→          <div class="panel-hd-left">
   908→            <span class="panel-title">Raw JSON</span>
   909→          </div>
   910→          <button class="btn-dl" onclick="downloadJson()">↓ Download</button>
   911→        </div>
   912→        <div id="json-output"></div>
   913→      </div>
   914→
   915→    </div>
   916→  </div>
   917→</div>
   918→
   919→<!-- Crawl results -->
   920→<div id="crawl-container">
   921→  <div class="crawl-hd">
   922→    <span class="crawl-title">Crawl Results</span>
   923→    <button class="btn-dl" onclick="downloadCrawlJson()">↓ JSON</button>
   924→  </div>
   925→  <div id="crawl-list" class="crawl-list"></div>
   926→</div>
   927→
   928→<script>
   929→let lastResult = null;
   930→let lastCrawlResult = null;
   931→let lastTab = 'images'; // remember which tab the user was on
   932→
   933→// ── Tabs ──────────────────────────────────────────
   934→function switchTab(name, btn) {
   935→  document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
   936→  document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
   937→  document.getElementById('tab-' + name).classList.add('active');
   938→  if (btn) btn.classList.add('active');
   939→  lastTab = name;
   940→}
   941→function switchTabByName(name) {
   942→  switchTab(name, document.getElementById('tab-btn-' + name));
   943→}
   944→
   945→// ── Status ──────────────────────────────────────────
   946→function setStatus(msg, type = '') {
   947→  document.getElementById('s-text').textContent = msg;
   948→  document.getElementById('s-dot').className = 's-dot ' + type;
   949→  document.getElementById('spinner').style.display = type === 'loading' ? 'inline-block' : 'none';
   950→}
   951→function setLoading(msg) { setStatus(msg, 'loading'); }
   952→function setError(msg)   { setStatus('error: ' + msg, 'error'); }
   953→function setOk(msg)      { setStatus(msg, 'ok'); }
   954→
   955→function setBusy(busy) {
   956→  document.getElementById('scrape-btn').disabled = busy;
   957→  document.getElementById('crawl-btn').disabled  = busy;
   958→}
   959→
   960→// ── Scrape ──────────────────────────────────────────
   961→async function doScrape() {
   962→  const url    = document.getElementById('url-input').value.trim();
   963→  const useApi = document.getElementById('use-api').checked;
   964→  if (!url) { setError('enter a url'); return; }
   965→  setLoading('scraping…');
   966→  setBusy(true);
   967→  clearResults();
   968→  try {
   969→    const res  = await fetch('/api/scrape', {
   970→      method: 'POST',
   971→      headers: { 'Content-Type': 'application/json' },
   972→      body: JSON.stringify({ url, useApi }),
   973→    });
   974→    const data = await res.json();
   975→    if (!res.ok) throw new Error(data.error + (data.tip ? ' — ' + data.tip : ''));
   976→    lastResult = data;
   977→    renderResult(data);
   978→    setOk(`${data.summary.images} images · ${data.summary.fonts} fonts · ${data.summary.files} files`);
   979→  } catch (e) {
   980→    setError(e.message);
   981→  } finally {
   982→    setBusy(false);
   983→  }
   984→}
   985→
   986→// ── Crawl ──────────────────────────────────────────
   987→async function doCrawl() {
   988→  const url        = document.getElementById('url-input').value.trim();
   989→  const maxPages   = parseInt(document.getElementById('max-pages').value) || 5;
   990→  const pathFilter = document.getElementById('path-filter').value || '.*';
   991→  const useApi     = document.getElementById('use-api').checked;
   992→  if (!url) { setError('enter a url'); return; }
   993→  setLoading(`crawling up to ${maxPages} pages…`);
   994→  setBusy(true);
   995→  clearResults();
   996→  try {
   997→    const res  = await fetch('/api/crawl', {
   998→      method: 'POST',
   999→      headers: { 'Content-Type': 'application/json' },
  1000→      body: JSON.stringify({ url, pathFilter, maxPages, useApi }),
  1001→    });
  1002→    const data = await res.json();
  1003→    if (!res.ok) throw new Error(data.error);
  1004→    lastCrawlResult = data;
  1005→    renderCrawlResults(data);
  1006→    setOk(`crawled ${data.pages} pages`);
  1007→  } catch (e) {
  1008→    setError(e.message);
  1009→  } finally {
  1010→    setBusy(false);
  1011→  }
  1012→}
  1013→
  1014→document.getElementById('url-input').addEventListener('keydown', e => {
  1015→  if (e.key === 'Enter' && !document.getElementById('scrape-btn').disabled) doScrape();
  1016→});
  1017→
  1018→// ── Clear ──────────────────────────────────────────
  1019→function clearResults() {
  1020→  document.getElementById('results').style.display = 'none';
  1021→  document.getElementById('crawl-container').style.display = 'none';
  1022→  document.getElementById('summary').style.display = 'none';
  1023→  document.getElementById('page-meta').style.display = 'none';
  1024→  lastResult = lastCrawlResult = null;
  1025→}
  1026→
  1027→// ── Render ──────────────────────────────────────────
  1028→function renderResult(data) {
  1029→  document.getElementById('crawl-container').style.display = 'none';
  1030→
  1031→  const m = document.getElementById('page-meta');
  1032→  m.style.display = 'block';
  1033→  m.innerHTML = `
  1034→    <div class="meta-title">${esc(data.meta.title || '(no title)')}</div>
  1035→    ${data.meta.description ? `<div class="meta-desc">${esc(data.meta.description.slice(0,160))}</div>` : ''}
  1036→    <div class="meta-sub">${esc(data.meta.url)} · ${data.meta.mode} · ${new Date(data.meta.scrapedAt).toLocaleTimeString()}</div>
  1037→  `;
  1038→
  1039→  const s = data.summary;
  1040→  document.getElementById('stat-images').textContent   = s.images;
  1041→  document.getElementById('stat-fonts').textContent    = s.fonts;
  1042→  document.getElementById('stat-files').textContent    = s.files;
  1043→  document.getElementById('stat-links').textContent    = s.internalLinks + s.externalLinks;
  1044→  document.getElementById('stat-products').textContent = s.productBlocks;
  1045→  document.getElementById('stat-headings').textContent = s.headings;
  1046→  document.getElementById('summary').style.display = 'block';
  1047→
  1048→  document.getElementById('results').style.display = 'block';
  1049→  // Restore the tab the user was on; fall back to images on first load
  1050→  switchTabByName(lastTab);
  1051→
  1052→  renderImages(data.images);
  1053→  renderFonts(data.fonts);
  1054→  renderFiles(data.files);
  1055→  renderLinks(data.links);
  1056→  renderProducts(data.productBlocks);
  1057→  renderHeadings(data.headings);
  1058→  renderJson(data);
  1059→}
  1060→
  1061→// ── Images ──────────────────────────────────────────
  1062→function renderImages(images) {
  1063→  const n = images.length;
  1064→  document.getElementById('img-count').textContent     = n;
  1065→  document.getElementById('img-count-sub').textContent = n + ' found';
  1066→  const el = document.getElementById('image-grid');
  1067→  if (!n) { el.innerHTML = empty('no images found'); return; }
  1068→  el.innerHTML = images.map(img => `
  1069→    <div class="img-cell">
  1070→      <img src="${esc(img.src)}" alt="${esc(img.alt)}"
  1071→        onerror="this.style.display='none';this.nextElementSibling.style.display='flex'" loading="lazy"/>
  1072→      <div class="img-err">☐</div>
  1073→      <div class="img-overlay">
  1074→        <span class="img-name">${esc(fileName(img.src))}</span>
  1075→        <a class="img-dl" href="/api/download?url=${enc(img.src)}&filename=${enc(fileName(img.src))}" download>↓</a>
  1076→      </div>
  1077→    </div>
  1078→  `).join('');
  1079→}
  1080→
  1081→// ── Fonts ──────────────────────────────────────────
  1082→function renderFonts(fonts) {
  1083→  const n = fonts.length;
  1084→  document.getElementById('font-count').textContent     = n;
  1085→  document.getElementById('font-count-sub').textContent = n + ' found';
  1086→  const el = document.getElementById('font-list');
  1087→  if (!n) { el.innerHTML = empty('no @font-face fonts found'); return; }
  1088→  el.innerHTML = fonts.map(f => `
  1089→    <div class="font-row">
  1090→      <div class="font-preview" style="font-family:'${esc(f.family)}',sans-serif;">Aa</div>
  1091→      <div class="font-info">
  1092→        <div class="font-name">${esc(f.family)}</div>
  1093→        <div class="font-meta">weight ${esc(f.weight)} · ${esc(f.style)}</div>
  1094→      </div>
  1095→      <div style="display:flex;gap:4px;flex-wrap:wrap;align-items:center;">
  1096→        ${f.sources.map(s => `<span class="tag">${s.format}</span>`).join('')}
  1097→      </div>
  1098→      <a class="btn-dl"
  1099→        href="/api/download?url=${enc(f.downloadUrl)}&filename=${enc(f.family+'-'+f.weight+'.'+f.format)}" download>
  1100→        ↓ ${f.format.toUpperCase()}
  1101→      </a>
  1102→    </div>
  1103→  `).join('');
  1104→}
  1105→
  1106→// ── Files ──────────────────────────────────────────
  1107→function renderFiles(files) {
  1108→  const n = files.length;
  1109→  document.getElementById('file-count').textContent     = n;
  1110→  document.getElementById('file-count-sub').textContent = n + ' found';
  1111→  const el = document.getElementById('file-list');
  1112→  if (!n) { el.innerHTML = empty('no downloadable files found'); return; }
  1113→  el.innerHTML = files.map(f => `
  1114→    <div class="file-row">
  1115→      <div class="file-type ${fileIconClass(f.ext)}">${esc(f.type)}</div>
  1116→      <div class="file-info">
  1117→        <div class="file-name">${esc(f.text.slice(0,80))}</div>
  1118→        <div class="file-path">${esc(fileName(f.url))}</div>
  1119→      </div>
  1120→      <a class="btn-dl"
  1121→        href="/api/download?url=${enc(f.url)}&filename=${enc(fileName(f.url))}" download>↓</a>
  1122→    </div>
  1123→  `).join('');
  1124→}
  1125→
  1126→// ── Links ──────────────────────────────────────────
  1127→function renderLinks({ internal, external }) {
  1128→  const n = internal.length + external.length;
  1129→  document.getElementById('link-count').textContent     = n;
  1130→  document.getElementById('link-count-sub').textContent = n + ' found';
  1131→  document.getElementById('link-list').innerHTML     = internal.length  ? internal.map(linkRow).join('')  : empty('no internal links');
  1132→  document.getElementById('ext-link-list').innerHTML = external.length ? external.map(linkRow).join('') : empty('no external links');
  1133→}
  1134→function linkRow(l) {
  1135→  return `
  1136→    <div class="link-row">
  1137→      <span class="link-text" title="${esc(l.text)}">${esc(l.text || '(no text)')}</span>
  1138→      <span class="link-href">${esc(l.href)}</span>
  1139→      <a class="link-ext" href="${esc(l.href)}" target="_blank" rel="noopener" title="Open">↗</a>
  1140→    </div>`;
  1141→}
  1142→
  1143→// ── Products ──────────────────────────────────────────
  1144→function renderProducts(blocks) {
  1145→  const n = blocks.length;
  1146→  document.getElementById('product-count').textContent     = n;
  1147→  document.getElementById('product-count-sub').textContent = n + ' found';
  1148→  const el = document.getElementById('product-grid');
  1149→  if (!n) { el.innerHTML = `<div style="padding:20px;">${empty('no pricing blocks found')}</div>`; return; }
  1150→  el.innerHTML = blocks.map(b => `
  1151→    <div class="product-cell">
  1152→      ${b.image ? `<img class="product-img" src="${esc(b.image)}" alt="" onerror="this.style.display='none'" loading="lazy"/>` : ''}
  1153→      ${b.heading ? `<div class="product-title">${esc(b.heading)}</div>` : ''}
  1154→      <div class="price-list">${b.prices.map(p => `<span class="price-item">${esc(p)}</span>`).join('')}</div>
  1155→      <div class="product-snip">${esc(b.snippet)}</div>
  1156→    </div>
  1157→  `).join('');
  1158→}
  1159→
  1160→// ── Headings ──────────────────────────────────────────
  1161→function renderHeadings(headings) {
  1162→  const n = headings.length;
  1163→  document.getElementById('heading-count').textContent     = n;
  1164→  document.getElementById('heading-count-sub').textContent = n + ' found';
  1165→  const el = document.getElementById('heading-list');
  1166→  if (!n) { el.innerHTML = empty('no headings found'); return; }
  1167→  el.innerHTML = headings.map(h => `
  1168→    <div class="heading-row">
  1169→      <span class="h-level">${esc(h.level)}</span>
  1170→      <span class="h-text">${esc(h.text)}</span>
  1171→    </div>
  1172→  `).join('');
  1173→}
  1174→
  1175→// ── JSON ──────────────────────────────────────────
  1176→function renderJson(data) {
  1177→  document.getElementById('json-output').innerHTML = syntaxHighlight(JSON.stringify(data, null, 2));
  1178→}
  1179→function downloadJson() {
  1180→  if (!lastResult) return;
  1181→  triggerDownload(JSON.stringify(lastResult, null, 2), 'scraper-result.json', 'application/json');
  1182→}
  1183→
  1184→// ── Crawl results ──────────────────────────────────────────
  1185→function renderCrawlResults(data) {
  1186→  document.getElementById('results').style.display = 'none';
  1187→  document.getElementById('summary').style.display = 'none';
  1188→  document.getElementById('crawl-container').style.display = 'block';
  1189→  document.getElementById('crawl-list').innerHTML = data.results.map((r, i) => {
  1190→    if (r.error) return `
  1191→      <div class="crawl-row" style="cursor:default;">
  1192→        <span class="crawl-row-title" style="color:var(--red)">Error — ${esc(r.url)}</span>
  1193→        <span class="chip">${esc(r.error)}</span>
  1194→      </div>`;
  1195→    const s = r.summary;
  1196→    return `
  1197→      <div class="crawl-row" onclick="openCrawlPage(${i})">
  1198→        <span class="crawl-row-title">${esc(r.meta.title || '(no title)')}</span>
  1199→        <span class="crawl-row-url">${esc(r.meta.url)}</span>
  1200→        <div class="crawl-chips">
  1201→          <span class="chip">${s.images} img</span>
  1202→          <span class="chip">${s.fonts} font</span>
  1203→          <span class="chip">${s.files} file</span>
  1204→          <span class="chip">${s.internalLinks} link</span>
  1205→        </div>
  1206→      </div>`;
  1207→  }).join('');
  1208→}
  1209→
  1210→function openCrawlPage(i) {
  1211→  if (!lastCrawlResult) return;
  1212→  const page = lastCrawlResult.results[i];
  1213→  if (!page || page.error || !page.meta) return; // guard against error results
  1214→  lastResult = page;
  1215→  document.getElementById('crawl-container').style.display = 'none';
  1216→  renderResult(page);
  1217→  setOk('showing: ' + page.meta.url);
  1218→}
  1219→function downloadCrawlJson() {
  1220→  if (!lastCrawlResult) return;
  1221→  triggerDownload(JSON.stringify(lastCrawlResult, null, 2), 'crawl-results.json', 'application/json');
  1222→}
  1223→
  1224→// ── Utils ──────────────────────────────────────────
  1225→function esc(s) {
  1226→  if (s == null) return '';
  1227→  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  1228→}
  1229→function enc(s) { return encodeURIComponent(s || ''); }
  1230→function fileName(url) {
  1231→  try { return decodeURIComponent(new URL(url).pathname.split('/').pop()) || url; }
  1232→  catch { return url; }
  1233→}
  1234→function fileIconClass(ext) {
  1235→  if (ext === 'pdf') return 'pdf';
  1236→  if (['zip','gz','tar','rar','7z'].includes(ext)) return 'zip';
  1237→  if (['doc','docx'].includes(ext)) return 'doc';
  1238→  if (['xls','xlsx','csv'].includes(ext)) return 'xlsx';
  1239→  return 'other';
  1240→}
  1241→function empty(msg) {
  1242→  return `<div class="empty"><div class="empty-n">—</div><div class="empty-msg">${esc(msg)}</div></div>`;
  1243→}
  1244→function triggerDownload(content, filename, type) {
  1245→  const blob = new Blob([content], { type });
  1246→  const objectUrl = URL.createObjectURL(blob);
  1247→  const a = Object.assign(document.createElement('a'), { href: objectUrl, download: filename });
  1248→  a.click();
  1249→  // Defer revoke so the browser has time to start the download
  1250→  setTimeout(() => URL.revokeObjectURL(objectUrl), 100);
  1251→}
  1252→function syntaxHighlight(json) {
  1253→  // HTML-escape first to prevent XSS from scraped page content
  1254→  const safe = json.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  1255→  return safe.replace(
  1256→    /("(\\u[a-zA-Z0-9]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(true|false|null)\b|-?\d+(?:\.\d*)?(?:[eE][+\-]?\d+)?)/g,
  1257→    m => {
  1258→      let c = 'json-num';
  1259→      if (/^"/.test(m)) c = /:$/.test(m) ? 'json-key' : 'json-str';
  1260→      else if (/true|false/.test(m)) c = 'json-bool';
  1261→      else if (/null/.test(m)) c = 'json-null';
  1262→      return `<span class="${c}">${m}</span>`;
  1263→    }
  1264→  );
  1265→}
  1266→</script>
